-- Marketplace hardening and catalog normalization.
-- All tier prices in this migration are planning proposals; do not enable checkout
-- until the pricing owner explicitly approves them and a payment adapter is configured.

alter table public.marketplace_packages add column if not exists pricing_status text not null default 'draft' check (pricing_status in ('draft','approved','retired'));
update public.marketplace_products set active_status='retired',visibility='hidden',updated_at=now() where product_key in ('helpbuddy-customization','intellchat');
update public.marketplace_products set package_keys=(select jsonb_agg(distinct case when value='"helpbuddy-customization"'::jsonb then '"helpbuddy"'::jsonb when value='"intellchat"'::jsonb then '"intellichat"'::jsonb else value end) from jsonb_array_elements(package_keys) x(value)),updated_at=now() where package_keys @> '["helpbuddy-customization"]'::jsonb or package_keys @> '["intellchat"]'::jsonb;
update public.marketplace_packages set included_product_keys=array(select distinct case when x='helpbuddy-customization' then 'helpbuddy' when x='intellchat' then 'intellichat' else x end from unnest(included_product_keys) x),updated_at=now() where included_product_keys && array['helpbuddy-customization','intellchat']::text[];
insert into public.marketplace_packages(package_key,name,description,included_product_keys,support_level,monthly_company_price,annual_company_price,is_recommended,active_status,sort_order,pricing_status) values
('launch','Launch','Proposed entry tier for small teams; price and scope require approval.',array['global-identity','optimus','help-desk','knowledge-base','intellichat'],'standard',99,990,false,'active',5,'draft'),
('basic','Basic','Core connected Command Center capabilities.',array['global-identity','optimus','help-desk','knowledge-base','intellichat'],'standard',199,1990,false,'active',10,'draft'),
('growth','Growth','Expanded collaboration and business operations.',array['global-identity','intellihire','helpbuddy','trinity','optimus','help-desk','intellichat','knowledge-base'],'standard',399,3990,false,'active',15,'draft'),
('premium','Premium','Expanded security, network and assistant capabilities.',array['global-identity','intellihire','helpbuddy','trinity','optimus','help-desk','security-operations','network-operations','intellichat','knowledge-base'],'premium',799,7990,true,'active',20,'draft'),
('enterprise','Enterprise','Broad operational platform for multi-team organizations.',array['global-identity','intellitax','intellipay','intellihire','helpbuddy','trinity','optimus','help-desk','security-operations','network-operations','intellichat','knowledge-base','workflow-automation'],'premium',1499,14990,false,'active',25,'draft'),
('full-experience','Full Experience','Comprehensive catalog bundle including Maximus and governed automation.',array['global-identity','intellitax','intellipay','intellihire','helpbuddy','trinity','optimus','maximus','help-desk','security-operations','network-operations','intellichat','knowledge-base','workflow-automation'],'premium',2499,24990,false,'active',30,'draft')
on conflict(package_key) do update set name=excluded.name,description=excluded.description,included_product_keys=excluded.included_product_keys,support_level=excluded.support_level,monthly_company_price=excluded.monthly_company_price,annual_company_price=excluded.annual_company_price,is_recommended=excluded.is_recommended,active_status=excluded.active_status,sort_order=excluded.sort_order,pricing_status='draft',updated_at=now();
drop policy if exists marketplace_carts_owner_all on public.marketplace_carts;
create policy marketplace_carts_owner_all on public.marketplace_carts for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists marketplace_cart_items_owner_all on public.marketplace_cart_items;
create policy marketplace_cart_items_owner_all on public.marketplace_cart_items for all to authenticated using(exists(select 1 from public.marketplace_carts c where c.id=cart_id and c.user_id=auth.uid())) with check(exists(select 1 from public.marketplace_carts c where c.id=cart_id and c.user_id=auth.uid()));
drop policy if exists marketplace_saved_items_owner_all on public.marketplace_saved_items;
create policy marketplace_saved_items_owner_all on public.marketplace_saved_items for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists marketplace_price_calculations_owner_all on public.marketplace_price_calculations;
create policy marketplace_price_calculations_owner_all on public.marketplace_price_calculations for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists marketplace_orders_owner_read on public.marketplace_orders;
create policy marketplace_orders_owner_read on public.marketplace_orders for select to authenticated using(user_id=auth.uid());
drop policy if exists marketplace_order_items_owner_read on public.marketplace_order_items;
create policy marketplace_order_items_owner_read on public.marketplace_order_items for select to authenticated using(exists(select 1 from public.marketplace_orders o where o.id=order_id and o.user_id=auth.uid()));
drop policy if exists marketplace_subscriptions_owner_read on public.marketplace_subscriptions;
create policy marketplace_subscriptions_owner_read on public.marketplace_subscriptions for select to authenticated using(user_id=auth.uid());
drop policy if exists marketplace_subscription_items_owner_read on public.marketplace_subscription_items;
create policy marketplace_subscription_items_owner_read on public.marketplace_subscription_items for select to authenticated using(exists(select 1 from public.marketplace_subscriptions s where s.id=subscription_id and s.user_id=auth.uid()));
drop policy if exists marketplace_entitlements_scoped_read on public.marketplace_entitlements;
create policy marketplace_entitlements_scoped_read on public.marketplace_entitlements for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and ((organization_id is not null and p.organization_id=marketplace_entitlements.organization_id) or (tenant_id is not null and p.tenant_id=marketplace_entitlements.tenant_id))));
drop policy if exists marketplace_audit_events_scoped_read on public.marketplace_audit_events;
create policy marketplace_audit_events_scoped_read on public.marketplace_audit_events for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and ((organization_id is not null and p.organization_id=marketplace_audit_events.organization_id) or (tenant_id is not null and p.tenant_id=marketplace_audit_events.tenant_id))));
drop policy if exists marketplace_messages_participant_read on public.marketplace_messages;
create policy marketplace_messages_participant_read on public.marketplace_messages for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and (p.id=sender_profile_id or p.id=recipient_profile_id)));
drop policy if exists marketplace_messages_sender_insert on public.marketplace_messages;
create policy marketplace_messages_sender_insert on public.marketplace_messages for insert to authenticated with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.id=sender_profile_id));
drop policy if exists marketplace_messages_participant_update on public.marketplace_messages;
create policy marketplace_messages_participant_update on public.marketplace_messages for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and (p.id=sender_profile_id or p.id=recipient_profile_id))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and (p.id=sender_profile_id or p.id=recipient_profile_id)));
drop policy if exists marketplace_notifications_recipient_all on public.marketplace_notifications;
create policy marketplace_notifications_recipient_all on public.marketplace_notifications for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.id=recipient_profile_id)) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.id=recipient_profile_id));
drop policy if exists marketplace_products_admin_write on public.marketplace_products;
create policy marketplace_products_admin_write on public.marketplace_products for all to authenticated using(exists(select 1 from public.profile_roles pr join public.roles r on r.id=pr.role_id where pr.profile_id=auth.uid() and pr.is_active and lower(r.role_key) in ('super_admin','global_admin','marketplace_admin'))) with check(exists(select 1 from public.profile_roles pr join public.roles r on r.id=pr.role_id where pr.profile_id=auth.uid() and pr.is_active and lower(r.role_key) in ('super_admin','global_admin','marketplace_admin')));
drop policy if exists marketplace_packages_admin_write on public.marketplace_packages;
create policy marketplace_packages_admin_write on public.marketplace_packages for all to authenticated using(exists(select 1 from public.profile_roles pr join public.roles r on r.id=pr.role_id where pr.profile_id=auth.uid() and pr.is_active and lower(r.role_key) in ('super_admin','global_admin','marketplace_admin'))) with check(exists(select 1 from public.profile_roles pr join public.roles r on r.id=pr.role_id where pr.profile_id=auth.uid() and pr.is_active and lower(r.role_key) in ('super_admin','global_admin','marketplace_admin')));
drop policy if exists marketplace_prices_admin_write on public.marketplace_price_versions;
create policy marketplace_prices_admin_write on public.marketplace_price_versions for all to authenticated using(exists(select 1 from public.profile_roles pr join public.roles r on r.id=pr.role_id where pr.profile_id=auth.uid() and pr.is_active and lower(r.role_key) in ('super_admin','global_admin','marketplace_admin'))) with check(exists(select 1 from public.profile_roles pr join public.roles r on r.id=pr.role_id where pr.profile_id=auth.uid() and pr.is_active and lower(r.role_key) in ('super_admin','global_admin','marketplace_admin')));
